$('#modal').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))return closeModal();if(b.hasAttribute('data-aug'))return takeAug(Number(b.dataset.aug));if(b.hasAttribute('data-new')){clearInterval(timer);sim=null;s=fresh();s.shop=rndShop();selected=null;closeModal();return draw()}if(b.hasAttribute('data-collection'))return collection();if(b.hasAttribute('data-detail'))return details(b.dataset.detail);if(b.hasAttribute('data-emblems'))return emblemModal();if(b.hasAttribute('data-emblem')){let x=s.units.find(z=>z.id===b.dataset.emblem),em=s.emblems.shift();if(x&&em){x.emblems=x.emblems||[];x.emblems.push(em);pop(`${x.name}에게 ${em} 상징 장착`)}closeModal();draw()}});
